(function(){
  const $=selector=>document.querySelector(selector), $$=selector=>[...document.querySelectorAll(selector)];
  const labels={adult:'Adulto · 18+',baby:'Criança · até 3',child:'Criança · 4–8',youth:'Jovem · 9–17'};
  let responses=[],people=[],filter='all';
  const normalDiet=value=>{const text=String(value||'').trim();return !text||/^(nenhuma|não|nao|sem|n\/a)$/i.test(text)?'Nenhuma':text};
  const parseDetails=data=>{try{return typeof data.details==='string'?JSON.parse(data.details):(data.details||{})}catch(_){return {}}};
  const parseOldPerson=text=>{const parts=String(text).split(' — '),ageText=parts[1]||'',diet=(parts.slice(2).join(' — ').replace(/^Restrições:\s*/i,'')||'Nenhuma');let age='adult';if(/0.?3|até 3/i.test(ageText))age='baby';else if(/4.?8/i.test(ageText))age='child';else if(/9.?17/i.test(ageText))age='youth';return {nome:(parts[0]||'').replace(/^\d+\.\s*/,''),faixaEtaria:age,restricoes:diet}};
  function normalise(submission){const data=submission.data||{},details=parseDetails(data),coming=details.presenca===true||data.attendance==='Sim';let persons=Array.isArray(details.pessoasDetalhes)?details.pessoasDetalhes:(Array.isArray(details.pessoas)?details.pessoas.map(parseOldPerson):[]);return{id:submission.id,date:details.dataResposta||submission.created_at,responsavel:details.responsavel||data.name||'Sem nome',coming,total:Number(details.total||data.guests||0),persons:persons.map(person=>({nome:person.nome||'Sem nome',age:person.faixaEtaria||'adult',diet:normalDiet(person.restricoes),responsavel:details.responsavel||data.name||'Sem nome'}))}}
  function escapeCsv(value){return '"'+String(value??'').replace(/"/g,'""')+'"'}
  function render(){
    const confirmed=responses.filter(r=>r.coming),declined=responses.filter(r=>!r.coming);people=confirmed.flatMap(r=>r.persons);
    const count=age=>people.filter(p=>p.age===age).length;
    const cards=[['Respostas positivas',confirmed.length],['Total de pessoas',people.length],['Adultos',count('adult')],['Até 3 anos',count('baby')],['4–8 anos',count('child')],['9–17 anos',count('youth')]];
    $('#stats').innerHTML=cards.map(([label,value])=>'<article class="stat"><strong>'+value+'</strong><span>'+label+'</span></article>').join('');
    const query=$('#search').value.trim().toLowerCase();let shown=people.filter(p=>(filter==='all'||filter==='diet'&&p.diet!=='Nenhuma'||p.age===filter)&&(!query||(p.nome+' '+p.responsavel+' '+p.diet).toLowerCase().includes(query)));
    $('#people-body').innerHTML=shown.map(p=>'<tr><td>'+safe(p.nome)+'</td><td><span class="tag">'+safe(labels[p.age]||p.age)+'</span></td><td>'+safe(p.responsavel)+'</td><td>'+safe(p.diet)+'</td></tr>').join('');$('#people-empty').hidden=shown.length>0;
    $('#groups').innerHTML=confirmed.map(r=>'<article class="group"><h3>'+safe(r.responsavel)+'</h3><p>'+r.persons.length+' '+(r.persons.length===1?'pessoa':'pessoas')+' · '+new Date(r.date).toLocaleDateString('pt-PT')+'</p><ul>'+r.persons.map(p=>'<li>'+safe(p.nome)+' — '+safe(labels[p.age]||p.age)+(p.diet!=='Nenhuma'?' · '+safe(p.diet):'')+'</li>').join('')+'</ul><button class="delete-entry" data-delete="'+safe(r.id)+'" type="button">Eliminar resposta</button></article>').join('')||'<p>Ainda não existem confirmações positivas.</p>';
    $('#declined-total').textContent=declined.length;$('#declined-list').innerHTML=declined.map(r=>'<li>'+safe(r.responsavel)+' <button class="delete-entry" data-delete="'+safe(r.id)+'" type="button">Eliminar</button></li>').join('')||'<li>Nenhuma resposta negativa.</li>';
  }
  function safe(value){const node=document.createElement('span');node.textContent=String(value);return node.innerHTML}
  async function adminRequest(options={}){const password=$('#password').value||sessionStorage.getItem('wedding_admin_password')||'',response=await fetch('/api/respostas',{...options,headers:{'X-Admin-Password':password,'Accept':'application/json','Content-Type':'application/json',...(options.headers||{})},cache:'no-store'}),raw=await response.text();let data;try{data=JSON.parse(raw)}catch(_){throw new Error('A função de respostas não está ativa ou ainda está a usar uma versão anterior. Faz um novo deploy.')}if(!response.ok)throw new Error(data.erro||'Não foi possível concluir a operação.');return data}
  async function load(){const password=$('#password').value||sessionStorage.getItem('wedding_admin_password')||'';document.body.classList.add('loading');$('#notice').textContent='A carregar respostas…';try{const response=await fetch('/api/respostas',{headers:{'X-Admin-Password':password,'Accept':'application/json'},cache:'no-store'}),raw=await response.text();let data;try{data=JSON.parse(raw)}catch(_){throw new Error('A função de respostas não está ativa. Publica o projeto completo através de Git ou Netlify CLI e confirma as variáveis NETLIFY_API_TOKEN e ADMIN_PASSWORD.')}if(!response.ok)throw new Error(data.erro||'Não foi possível carregar.');sessionStorage.setItem('wedding_admin_password',password);responses=(data.submissions||[]).map(normalise).sort((a,b)=>new Date(b.date)-new Date(a.date));$('#login').hidden=true;$('#dashboard').hidden=false;$('#actions').hidden=false;$('#notice').textContent='Atualizado em '+new Date().toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'});render()}catch(error){$('#notice').textContent=error.message;$('#login').hidden=false}finally{document.body.classList.remove('loading')}}
  $('#login-form').addEventListener('submit',event=>{event.preventDefault();load()});$('#refresh').addEventListener('click',load);$('#search').addEventListener('input',render);$('#print').addEventListener('click',()=>window.print());
  $('#dashboard').addEventListener('click',async event=>{const button=event.target.closest('[data-delete]');if(!button)return;const response=responses.find(item=>item.id===button.dataset.delete);if(!confirm('Eliminar definitivamente a resposta de '+(response?.responsavel||'este convidado')+'?'))return;document.body.classList.add('loading');try{await adminRequest({method:'DELETE',body:JSON.stringify({id:button.dataset.delete})});responses=responses.filter(item=>item.id!==button.dataset.delete);render();$('#notice').textContent='Resposta eliminada.'}catch(error){$('#notice').textContent=error.message}finally{document.body.classList.remove('loading')}});
  $('#clear-all').addEventListener('click',async()=>{if(!responses.length){$('#notice').textContent='Não existem respostas para eliminar.';return}if(!confirm('Eliminar definitivamente TODAS as '+responses.length+' respostas? Esta ação não pode ser anulada.'))return;document.body.classList.add('loading');try{const data=await adminRequest({method:'DELETE',body:JSON.stringify({all:true})});responses=[];render();$('#notice').textContent=data.deleted+' respostas eliminadas.'}catch(error){$('#notice').textContent=error.message}finally{document.body.classList.remove('loading')}});
  $$('.filters button').forEach(button=>button.addEventListener('click',()=>{$$('.filters button').forEach(item=>item.classList.remove('active'));button.classList.add('active');filter=button.dataset.filter;$('#people-title').textContent=button.textContent;render()}));
  $('#export').addEventListener('click',()=>{const rows=[['Nome','Faixa etária','Grupo / responsável','Restrições alimentares'],...people.map(p=>[p.nome,labels[p.age]||p.age,p.responsavel,p.diet])],blob=new Blob(['\ufeff'+rows.map(row=>row.map(escapeCsv).join(';')).join('\n')],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='confirmacoes-alessandro-marina.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});
  if(sessionStorage.getItem('wedding_admin_password'))load();
}());
